// Extraction Skill + domain module + expert examples, then the source text from the library.
const files = $('Load Skills + Examples').all(), texts = $('Files to Text').all();
const src = $('Load Source').first().json;
const domain = String($('Source to Process').first().json.domain || '');
const DOMAINS = {"All domains": "", "Healthcare": "healthcare", "Public service": "public_service", "Agriculture": "agriculture", "Education": "education"};
const label = Object.keys(DOMAINS).find(k => DOMAINS[k] === domain) || domain;
const domainKeys = Object.values(DOMAINS).filter(Boolean);
let skill = '', module = '', examples = [];
texts.forEach((t, i) => {
  const { fileName: name, directory: dir = '' } = files[i].binary.data;
  if (dir.endsWith('/extraction') && name === 'SKILL.md') skill = t.json.data;
  else if (dir.endsWith('/domains')) { if (domain && name === `${domain}.md`) module = t.json.data; }
  else if (dir.includes('/extraction') && !name.startsWith('_')) {
    // an example named "<domain>-....md" is only used in runs of that domain; others in every run
    const own = domainKeys.find(d => name.startsWith(d + '-'));
    if (!own || own === domain) examples.push(`### Expert example: ${name}\n${t.json.data}`);
  }
});
const doc = String($input.first().json.text || '').replace(/\s+/g, ' ').trim();
const head = `URL: ${src.url}\nCountry: ${src.country}\nLanguage: ${src.language}` + (module ? `\nDomain of this run: ${label}` : '');
// the deployment the organiser placed this source in (context only: extract what THIS source says)
const dep = src.placed_deployment || {};
const others = (Array.isArray(src.placed_others) ? src.placed_others : []).slice(0, 8);
const ctx = src.placed_code ? `\n\n## Deployment this source was grouped under (context only)\nBefore this analysis the sources were organised into ` +
  `deployments. This source was placed in ${src.placed_code} "${src.placed_name}"${src.tool_code ? `, a deployment of the tool ${src.tool_code} "${src.tool_name}"` +
  `${src.tool_developer ? ' (' + src.tool_developer + ')' : ''}` : ''}${src.placed_org ? `, run by ${src.placed_org}` : ''}` +
  `${dep.place ? `, ${dep.place}` : ''}${dep.phase ? `, ${dep.phase}` : ''}.${src.placed_reason ? ' Why: ' + src.placed_reason : ''}\n` +
  (others.length ? `Other sources about it: ${others.map(o => `[S${o.sid}] ${o.title} (${o.type})`).join('; ')}.\n` : '') +
  `Use this only to name the project consistently (project.name: this deployment's name; technology.model_or_product: the tool). Extract ` +
  `only what THIS source says; if the source is clearly about another deployment, describe what the source says and explain it in ` +
  `interpretation.gaps.` : '';
return [{ json: { source_id: src.id, domain, fulltext: doc,
  prompt: `${skill}${module ? `\n\n---\n\n# Domain module for this run: ${label}\n\n${module}` : ''}\n\n` +
          `## Worked examples from our experts\n${examples.join('\n\n') || '(none yet)'}${ctx}\n\n## Source to analyse\n${head}\n\n${doc.slice(0, 80000)}` } }];

// 1. Check every quote occurs in the source text. 2. Compute the relevance score (Extraction Skill section 9):
//    five criteria x 20 points; a criterion counts only if its fields are filled AND one of its quotes was found.
const ctx = $('Compose Prompt').first().json;
const out = $input.first().json.output;
const x = out || {};
// compare without whitespace: text extraction can drop or add spaces (e.g. after Bengali vowel signs)
const norm = (s) => String(s || '').normalize('NFC').replace(/[\s\u200b-\u200d]+/g, '').toLowerCase();
const text = norm(ctx.fulltext);
const evidence = (x.evidence || []).map(e => ({ ...e, found: !!e.quote_original && text.includes(norm(e.quote_original).slice(0, 100)) }));
const supported = (block, name) => evidence.some(e => e.found && ((block?.evidence_refs || []).includes(e.id) || e.field === name));
const foundIds = new Set(evidence.filter(e => e.found).map(e => e.id));
// outcome rows and domain fields each cite one quote: mark whether it was found
const outcomes = (x.outcomes || []).map(o => ({ ...o, verified: foundIds.has(o.evidence_ref) }));
const domainFields = (x.domain_fields || []).map(d => ({ ...d, verified: foundIds.has(d.evidence_ref) }));
const filled = (v) => v !== null && v !== undefined && String(v).trim() !== '';
const p = x.project || {}, t = x.technology || {}, loc = x.location || {};
const criteria = [
  ['technology', 'AI technology specified',
   filled(t.specific) && filled(t.category) && t.category !== 'unspecified' && supported(t, 'technology')],
  ['purpose', 'Social purpose and beneficiaries',
   filled(p.domain) && p.domain !== 'other' && filled(p.target_beneficiaries) && supported(p, 'project')],
  ['location', 'Specific location',
   (loc.places || []).some(pl => ['admin1', 'admin2', 'city', 'site'].includes(pl.level)) && supported(loc, 'location')],
  ['implementation', 'Concrete implementation',
   filled(p.implementing_org) && ['pilot', 'scaled', 'discontinued'].includes(p.deployment_stage) && supported(p, 'project')],
  ['quantified', 'Quantified facts',
   (x.cost?.stated && Number(x.cost?.amount) > 0 && supported(x.cost, 'cost')) ||
   (x.reach?.stated && Number(x.reach?.number) > 0 && supported(x.reach, 'reach')) ||
   (x.benefit?.stated && filled(x.benefit?.magnitude) && supported(x.benefit, 'benefit')) ||
   outcomes.some(o => o.value !== null && o.value !== undefined && o.value !== '' && Number.isFinite(Number(o.value)) && o.verified)],
].map(([key, label, met]) => ({ key, label, met: !!met, points: met ? 20 : 0 }));
const score = out ? criteria.reduce((sum, c) => sum + c.points, 0) : 0;
const found = evidence.filter(e => e.found).length;
const flags = [];
if (!out) flags.push('extraction_failed');
if ((ctx.fulltext || '').length < 40) flags.push('no_text_extracted');
else if ((ctx.fulltext || '').length < 3000) flags.push('abstract_only');
if (x.cost?.stated && !supported(x.cost, 'cost')) flags.push('cost_without_evidence');
if (x.benefit?.stated && !supported(x.benefit, 'benefit')) flags.push('benefit_without_evidence');
if (evidence.some(e => !e.found)) flags.push('quote_not_found');
if (outcomes.some(o => !o.verified)) flags.push('outcome_without_evidence');
return [{ json: { source_id: ctx.source_id, flags, relevance_score: score,
  fields: out ? { ...x, run_domain: ctx.domain || '', outcomes, domain_fields: domainFields, evidence,
                  relevance: { score, criteria, quotes_found: found, quotes_total: evidence.length } } : null } }];

const STOP = new Set(['the','a','an','of','for','and','in','on','to','with','by','from','at','project','programme','program','pilot',
  'initiative','system','platform','tool','app','application','ai','artificial','intelligence','based','using','study','trial',
  'evaluation','scheme','model','national','smart','digital','new','phase','service','services']);
const toks = (s) => new Set(String(s || '').toLowerCase().normalize('NFKD').replace(/[^\p{L}\p{N}]+/gu, ' ').split(' ')
  .filter(w => w && !STOP.has(w)));
const overlap = (a, b) => { const A = toks(a), B = toks(b); if (!A.size || !B.size) return 0;
  let i = 0; A.forEach(w => { if (B.has(w)) i++; }); return i / Math.min(A.size, B.size); };
const sameCountry = (country, list) => !country || !Array.isArray(list) || !list.length ||
  list.some(c => String(c).toLowerCase() === String(country).toLowerCase());
// how strongly a source (project name guess, organisation, country) points at an existing project: 0..1
function projectScore(guess, org, country, p) {
  if (!sameCountry(country, p.countries)) return 0;
  const names = [p.name, ...(Array.isArray(p.aliases) ? p.aliases : [])];
  let s = Math.max(0, ...names.map(n => overlap(guess, n)));
  if (org && p.implementing_org && overlap(org, p.implementing_org) >= 0.6) s = Math.min(1, s + 0.25);
  return s;
}
const guessKey = (g) => [...toks(g)].sort().join(' ');
// Linking a source (or a project) to a known project: the name, the organisation, the places and the AI products all count.
const GENERIC = new Set(['cxr','chest','ray','xray','software','version','deep','learning','algorithm','algorithms','model','models','system',
  'tool','cad','detection','reader','screening','computer','aided','assisted','insight','based']);
const prodToks = (list) => { const out = new Set(); (Array.isArray(list) ? list : [list]).forEach(x => toks(x).forEach(w => {
  if (w.length >= 3 && !GENERIC.has(w) && !/^v?\d[\d.]*$/.test(w)) out.add(w); })); return out; };
const placeKeys = (places, fine) => new Set((Array.isArray(places) ? places : []).filter(pl => pl && (!fine || ['admin2', 'city', 'site'].includes(pl.level)))
  .flatMap(pl => fine ? [pl.name] : [pl.name, pl.admin1]).filter(Boolean).map(x => String(x).toLowerCase().trim()));
const lc = (x) => String(x || '').toLowerCase().trim();
// organisations match when they share at least two distinctive words, or one long distinctive word when a side has only one
const ORGSTOP = new Set(['ministry','department','health','university','hospital','centre','center','international','research','government',
  'foundation','institute','organisation','organization','office','division','society','association','limited','ltd','inc','private']);
function orgMatch(a, b) {
  const A = [...toks(a)].filter(w => !ORGSTOP.has(w)), B = new Set([...toks(b)].filter(w => !ORGSTOP.has(w)));
  const shared = A.filter(w => B.has(w));
  return shared.length >= 2 || (shared.length === 1 && Math.min(A.length, B.size) === 1 && shared[0].length >= 5);
}
function linkScore(me, p) {
  const sy = p.synthesis || {};
  const pc = [...(p.countries || []), ...(sy.countries || [])].map(lc);
  if (me.countries.length && pc.length && !me.countries.some(c => pc.includes(lc(c)))) return { score: 0, why: [] };
  const names = [p.name, ...(p.aliases || []), ...(sy.names || [])].filter(Boolean);
  let score = Math.max(0, ...names.map(n => overlap(me.name, n)));
  const why = score >= 0.5 ? ['similar name'] : [];
  const orgs = [p.implementing_org, ...(sy.orgs || [])].filter(Boolean);
  if (me.org && orgs.some(o => orgMatch(me.org, o))) { score += 0.35; why.push('same organisation'); }
  const fa = placeKeys(me.places, true), fb = placeKeys(sy.places, true);
  if ([...fa].some(x => fb.has(x))) { score += 0.2; why.push('same place'); }
  else { const a = placeKeys(me.places, false), b = placeKeys(sy.places, false); if ([...a].some(x => b.has(x))) { score += 0.1; why.push('same region'); } }
  const pa = prodToks(me.products), pb = prodToks(sy.products || []);
  if ([...pa].some(x => pb.has(x))) { score += 0.25; why.push('same AI product'); }
  return { score: Math.min(1, Math.round(score * 100) / 100), why };
}
// the definition comes from the Extraction Skill (section "One project, many sources"), so experts can change it
const DEFAULT_DEFINITION = 'A project is one programme that puts AI into use for a social purpose: who runs it, what the AI does for whom, ' +
  'and where. Several studies, reports or news about the same programme, its phases, sites and software versions, and several products ' +
  'compared within it are ONE project. Unrelated organisations each adopting the same commercial product are different projects.';
function projectDefinition(skillText) {
  const m = String(skillText || '').match(/\n## \d+\.\s*One project, many sources[^\n]*\n([\s\S]*?)(?=\n## |\s*$)/);
  return m ? m[1].trim() : DEFAULT_DEFINITION;
}
const describe = (x) => [`Project: ${x.name || 'unnamed'}`, `Run by: ${x.org || 'not stated'}`, `Countries: ${(x.countries || []).join(', ') || 'not stated'}`,
  `Places: ${[...new Set((x.places || []).map(pl => pl.name).filter(Boolean))].slice(0, 8).join(', ') || 'not stated'}`,
  `AI products: ${(Array.isArray(x.products) ? x.products : [x.products]).filter(Boolean).join('; ') || 'not stated'}`,
  `What it is: ${String(x.summary || '').slice(0, 900)}`].join('\n');
function judgePrompt(definition, me, cands) {
  return `## Same project check\nSources about the same project (deployment) are shown together to the experts, so they must be linked.\n\n` +
    `### What counts as one project\n${definition}\n\n### New item\n${describe(me)}\n\n### Known projects (suggested because of: name, organisation, place or product)\n` +
    cands.map(c => `#### ${c.code} (${(c.why || []).join(', ') || 'similar'}; ${c.sources || 1} source${c.sources > 1 ? 's' : ''})\n${describe(c)}`).join('\n\n') +
    `\n\nIs the new item about the SAME project as one of the known projects, by the definition above? ` +
    `Return same_as: that project's code (e.g. P-00012) or "" if none, and reason: one English sentence.`;
}
const projectView = (p) => { const sy = p.synthesis || {}; return { code: p.code, id: p.id, name: p.name, sources: Number(p.sources) || 1,
  org: p.implementing_org || (sy.orgs || [])[0] || '', countries: sy.countries || p.countries || [], places: sy.places || [],
  products: sy.products || [], summary: (sy.llm && sy.llm.summary) || p.summary || '' }; };

// Candidates among known projects: same country, and a similar name, the same organisation, place or AI product.
// The model judges every candidate set with the experts' definition of one project (Extraction Skill, section 10).
const f = $('Verify Evidence').first().json.fields || {};
const p = f.project || {};
const name = p.name || $('Load Source').first().json.project_guess || f.headline || '';
const countries = Array.isArray(p.countries) && p.countries.length ? p.countries : [$('Load Source').first().json.country];
const me = { name, org: p.implementing_org || '', countries, places: (f.location || {}).places || [],
             products: [f.technology?.model_or_product].filter(Boolean), domain: $('Source to Process').first().json.domain || '',
             summary: [f.headline, f.source?.summary_en].filter(Boolean).join(' ') };
const projects = $input.all().map(i => i.json).filter(x => x.id);
const scored = projects.map(x => ({ x, ...linkScore(me, x) })).filter(c => c.score >= 0.5)
  .sort((a, b) => b.score - a.score).slice(0, 4).map(c => ({ ...projectView(c.x), score: c.score, why: c.why }));
let skill = '';
$('Files to Text').all().forEach((t, i) => { const b = $('Load Skills + Examples').all()[i].binary.data;
  if ((b.directory || '').endsWith('/extraction') && b.fileName === 'SKILL.md') skill = t.json.data; });
const prompt = judgePrompt(projectDefinition(skill), me, scored);
return [{ json: { me, candidates: scored.map(({ id, code, name, score, why }) => ({ id, code, name, score, why })), prompt } }];

// The model's answer counts only if it names one of the offered candidates; otherwise a new project is created.
const m = $('Match Project').first().json;
let judge = null; try { judge = $('Same Project?').first().json.output || null; } catch (e) {}
const hit = judge && m.candidates.find(c => c.code === String(judge.same_as || '').trim());
return [{ json: { source_id: $('Load Source').first().json.id, project_id: hit ? hit.id : null,
  name: m.me.name || 'Unnamed project', org: m.me.org, countries: m.me.countries, domain: m.me.domain, summary: m.me.summary.slice(0, 600),
  method: hit ? 'llm' : 'new', product: String((m.me.products || [])[0] || '').split(/\s*;\s*/)[0].slice(0, 200),
  reason: hit ? `${judge.reason} (suggested because of: ${(hit.why || []).join(', ')})`
              : (judge ? `Checked against ${m.candidates.map(c => c.code).join(', ')}: ${judge.reason || 'not the same'}` : 'No similar project known') } }];

